update public.order_line
set
  unit_sell_price = case id
    when 'aaaa1111-1111-1111-1111-111111111111' then 18500
    when 'aaaa2222-2222-2222-2222-222222222222' then 24900
    when 'aaaa3333-3333-3333-3333-333333333333' then 13250
    when 'aaaa4444-4444-4444-4444-444444444444' then 45
    else unit_sell_price
  end,
  line_sell_price = case id
    when 'aaaa1111-1111-1111-1111-111111111111' then 18500
    when 'aaaa2222-2222-2222-2222-222222222222' then 24900
    when 'aaaa3333-3333-3333-3333-333333333333' then 26500
    when 'aaaa4444-4444-4444-4444-444444444444' then 135
    else line_sell_price
  end
where id in (
  'aaaa1111-1111-1111-1111-111111111111',
  'aaaa2222-2222-2222-2222-222222222222',
  'aaaa3333-3333-3333-3333-333333333333',
  'aaaa4444-4444-4444-4444-444444444444'
);

